-- ======== RDOs (cabeçalho). retifica_de / retificado_por entram depois, por apontarem para outros RDOs ========

-- O gatilho de atualizado_em é desligado só para não alterar a data original dos RDOs.
alter table rdos disable trigger rdos_atualizado_em;
update rdos set retifica_de = NULL, retificado_por = 'rdo_beta_0003_v2' where id = 'rdo_beta_0003';
update rdos set retifica_de = 'rdo_beta_0003', retificado_por = NULL where id = 'rdo_beta_0003_v2';
alter table rdos enable trigger rdos_atualizado_em;


